"""Complete native build tasks. Signing and timing-controller correctness checks excluded."""
from pathlib import Path
import subprocess,os,time,json,hashlib,random,statistics,platform
R=Path(__file__).resolve().parents[1];D=R/'artifacts/incremental'/('bench-'+str(time.time_ns()));D.mkdir(parents=True);B=Path(os.environ['RF2_BUILD_BIN']).resolve();C=Path(os.environ['RF2_TEST_COMPILER']).resolve();cache=D/'cache';cache.mkdir(mode=0o700);trials=int(os.environ.get('RF2_BENCH_TRIALS','21'));assert 5<=trials<=101
runtime=D/'runtime.rf2';runtime.write_text(''.join((R/x).read_text()for x in ['native/rf2.rf2','native/core.rf2','native/attendance.rf2','native/attendance-kernel.rf2','native/fingerprint.rf2','native/invoice.rf2','native/invoice-kernel.rf2','native/prepared.rf2','native/workspace.rf2','native/editor.rf2']))
tasks=[('native compiler',R/'native/compiler/compiler.rf2'),('native runtime',runtime),('modular checksum app',R/'examples/file-checksum.rf2')];raw=[];oracles={}
for name,source in tasks:
 out=D/('oracle-'+str(len(oracles)));subprocess.run([C,source,out,'--opt'],capture_output=True,check=True,env={'PATH':'/nonexistent'});expected=out.read_bytes();oracles[name]=hashlib.sha256(expected).hexdigest();out=D/('warm-'+str(len(oracles)));q=subprocess.run([B,C,source,out,cache,'--opt'],capture_output=True,check=True,env={'PATH':'/nonexistent'});assert out.read_bytes()==expected and json.loads(q.stdout)['cache']=='miss'
 for trial in range(trials):
  order=['direct clean','builder forced clean','builder warm reuse'];random.Random(261113+trial).shuffle(order)
  for variant in order:
   out=D/f'out-{len(raw)}';cmd=[C,source,out,'--opt']if variant=='direct clean'else[B,C,source,out,cache,'--opt']+(['--clean']if variant=='builder forced clean'else[]);start=time.perf_counter_ns();q=subprocess.run(cmd,capture_output=True,timeout=30,env={'PATH':'/nonexistent'});ms=(time.perf_counter_ns()-start)/1e6;assert q.returncode==0,(name,variant,q.stderr);assert out.read_bytes()==expected,(name,variant,'bytes differ');receipt=None
   if variant!='direct clean':receipt=json.loads(q.stdout);assert receipt['cache']==('miss'if variant=='builder forced clean'else'hit'),receipt
   raw.append({'task':name,'trial':trial,'variant':variant,'ms':ms,'receipt':receipt});out.unlink()
rows=[]
for name,_ in tasks:
 med={v:statistics.median(x['ms']for x in raw if x['task']==name and x['variant']==v)for v in ['direct clean','builder forced clean','builder warm reuse']};a=[x['ms']for x in raw if x['task']==name and x['variant']=='direct clean'];b=[x['ms']for x in raw if x['task']==name and x['variant']=='builder warm reuse'];delta=[y-x for x,y in zip(a,b)];rng=random.Random(261113);bs=sorted(statistics.median(rng.choices(delta,k=trials))for _ in range(10000));rows.append({'task':name,'medianMs':med,'directCleanOverWarmRatio':med['direct clean']/med['builder warm reuse'],'warmMinusDirectPairedMedianMs':statistics.median(delta),'pairedBootstrap95Ms':[bs[250],bs[9749]]})
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();report={'schema':'rf2.incremental.measurements.v1','passed':True,'trialsPerTaskVariant':trials,'options':['--opt'],'rows':rows,'raw':raw,'outputSHA256':oracles,'builderSHA256':sha(B),'compilerSHA256':sha(C),'controllerSHA256':sha(Path(__file__)),'host':platform.platform(),'limits':'One host, warm OS filesystem, process-inclusive startup/read/hash/compile-or-reuse/write. Native builder adds snapshots, integrity checks, fsync and atomic output publication; direct compiler does not provide all these guarantees. Signing/acceptance checks excluded. Cache misses remain full target compilation. No Clang/Python runtime, cross-host, energy or billed-token comparison.'};(D/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'report':str(D/'report.json'),'rows':rows}))
